WITH valid AS (SELECT id, device_code, reading_ts, temp_c, humidity, status_bits, CASE WHEN pressure >= 1029 THEN 'High' WHEN pressure >= 997 THEN 'Medium' ELSE 'Low' END pressure_level FROM device_readings WHERE reading_ts >= TIMESTAMP '2025-09-01 06:00:00') SELECT id, temp_c, status_bits, pressure_level FROM valid QUALIFY RANK() OVER (PARTITION BY device_code ORDER BY humidity NULLS FIRST) = 1;
